solution.Directory.java:
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

class Directory {
    private final Map<String, Person> byId = new HashMap<>();

    Directory(List<Person> people) {
        for (Person p : people) byId.put(p.id(), p);
    }

    Optional<Person> find(String id) { return Optional.ofNullable(byId.get(id)); }

    Optional<String> managerName(String id) {
        return find(id).map(Person::managerId).flatMap(this::find).map(Person::name);
    }

    String cityOf(String id) {
        return find(id).map(Person::city).filter(c -> !c.isBlank()).orElse("unknown");
    }

    Optional<Person> oldest() {
        return byId.values().stream().min(Comparator.comparing(Person::born));
    }

    static int age(LocalDate born, LocalDate today) {
        return Period.between(born, today).getYears();
    }

    static long daysUntilBirthday(LocalDate born, LocalDate today) {
        LocalDate next = birthdayIn(born, today.getYear());
        if (next.isBefore(today)) next = birthdayIn(born, today.getYear() + 1);
        return ChronoUnit.DAYS.between(today, next);
    }

    private static LocalDate birthdayIn(LocalDate born, int year) {
        return born.withYear(year);      // withYear turns Feb 29 into Feb 28 in years without it
    }
}

unitTests:
Directory dir = new Directory(List.of(
    new Person("1", "Ada", null, "London", LocalDate.of(1990, 12, 10)),
    new Person("2", "Grace", "1", null, LocalDate.of(1985, 3, 1)),
    new Person("3", "Linus", "9", "Helsinki", LocalDate.of(2000, 2, 29)),
    new Person("4", "Alan", "2", " ", LocalDate.of(1985, 3, 1))));

test("finding people", () -> {
    checkEq(dir.find("1").map(Person::name).orElse("-"), "Ada");
    checkEq(dir.find("8").map(Person::name).orElse("-"), "-");
    checkEq(dir.managerName("2"), Optional.of("Ada"));
    checkEq(dir.managerName("4"), Optional.of("Grace"));
    checkEq(dir.managerName("1"), Optional.empty());
    checkEq(dir.managerName("3"), Optional.empty());
    checkEq(dir.managerName("8"), Optional.empty());
});

test("cities and the oldest", () -> {
    checkEq(dir.cityOf("3"), "Helsinki");
    checkEq(dir.cityOf("2"), "unknown");
    checkEq(dir.cityOf("4"), "unknown");
    checkEq(dir.cityOf("8"), "unknown");
    checkEq(dir.oldest().map(Person::born), Optional.of(LocalDate.of(1985, 3, 1)));
    checkEq(new Directory(List.of()).oldest(), Optional.empty());
});

test("dates", () -> {
    LocalDate today = LocalDate.of(2026, 3, 1);
    checkEq(Directory.age(LocalDate.of(1985, 3, 1), today), 41);
    checkEq(Directory.age(LocalDate.of(1990, 12, 10), today), 35);
    checkEq(Directory.daysUntilBirthday(LocalDate.of(1985, 3, 1), today), 0L);
    checkEq(Directory.daysUntilBirthday(LocalDate.of(1990, 3, 2), today), 1L);
    checkEq(Directory.daysUntilBirthday(LocalDate.of(1990, 2, 28), today), 364L);
    checkEq(Directory.daysUntilBirthday(LocalDate.of(2000, 2, 29), LocalDate.of(2026, 2, 27)), 1L);
    checkEq(Directory.daysUntilBirthday(LocalDate.of(2000, 2, 29), LocalDate.of(2027, 12, 31)), 60L);
});

